  Object.assign(dictionaries.en,{'Mit ChatGPT anmelden und TranslateOCR ausdrücklich die Plan-Nutzung erlauben.':'Sign in with ChatGPT and explicitly allow TranslateOCR to use your plan.','Übersetzen & PDF + Word →':'Translate & PDF + Word →','Die erkannten Prüffelder erscheinen hier.':'Detected fields for review will appear here.','Vollständigkeit aller Seiten, Stempel und handschriftlichen Zusätze':'Completeness of all pages, stamps, and handwritten notes','Namen, Daten und Dokumentnummern am Original geprüft':'Names, dates, and document numbers checked against the original','Alle Stempel, Siegel und handschriftlichen Zusätze im Original gesucht':'All stamps, seals, and handwritten notes checked in the original','Druckansicht, Tabellenumbrüche, Schriftzeichen und leere Seiten geprüft':'Print layout, table breaks, glyphs, and blank pages checked','Keine ausgelassenen oder erfundenen Angaben':'No content omitted or invented','Auch nicht erkannte Bereiche prüfen':'Check areas the system did not detect','Automatische Kontrollen ersetzen keine Sichtprüfung':'Automated checks do not replace visual review','Bitte zuerst die Prüffelder am Original bestätigen.':'Please confirm the review fields against the original first.','Deine Übersetzung ist bereit. Beschreibe deine Änderungen hier. Ich aktualisiere die Vorschau; du lädst die finale Fassung herunter, wenn du zufrieden bist.':'Your translation is ready. Describe any changes here and I will update the preview. Download the final version when you are satisfied.','Deine PDF wird erstellt':'Creating your PDF','Noch ca.':'About','Vergangen:':'Elapsed:','Zur Warteschlange +':'Add to queue +'});
  Object.assign(dictionaries.ar,{'Mit ChatGPT anmelden und TranslateOCR ausdrücklich die Plan-Nutzung erlauben.':'سجّل الدخول إلى ChatGPT واسمح صراحةً لـ TranslateOCR باستخدام خطتك.','Übersetzen & PDF + Word →':'ترجمة وإنشاء PDF وWord ←','Die erkannten Prüffelder erscheinen hier.':'ستظهر هنا الحقول التي تم التعرّف عليها للمراجعة.','Vollständigkeit aller Seiten, Stempel und handschriftlichen Zusätze':'اكتمال جميع الصفحات والأختام والإضافات المكتوبة بخط اليد','Namen, Daten und Dokumentnummern am Original geprüft':'تمت مراجعة الأسماء والتواريخ وأرقام الوثائق بالرجوع إلى الأصل','Alle Stempel, Siegel und handschriftlichen Zusätze im Original gesucht':'تم البحث عن جميع الأختام والتواقيع والإضافات المكتوبة بخط اليد في الأصل','Druckansicht, Tabellenumbrüche, Schriftzeichen und leere Seiten geprüft':'تمت مراجعة الطباعة وفواصل الجداول والرموز والصفحات الفارغة','Keine ausgelassenen oder erfundenen Angaben':'لا توجد معلومات محذوفة أو مختلقة','Auch nicht erkannte Bereiche prüfen':'راجع أيضاً المواضع التي لم يتم التعرّف عليها','Automatische Kontrollen ersetzen keine Sichtprüfung':'لا تغني الفحوص الآلية عن المراجعة البصرية','Bitte zuerst die Prüffelder am Original bestätigen.':'يرجى تأكيد حقول المراجعة بالرجوع إلى المستند الأصلي أولاً.','Deine Übersetzung ist bereit. Beschreibe deine Änderungen hier. Ich aktualisiere die Vorschau; du lädst die finale Fassung herunter, wenn du zufrieden bist.':'ترجمتك جاهزة. اكتب التعديلات المطلوبة هنا وسأحدّث المعاينة. نزّل النسخة النهائية عندما تكون راضياً عنها.','Deine PDF wird erstellt':'جارٍ إنشاء ملف PDF','Zur Warteschlange +':'إضافة إلى قائمة الانتظار +'});
  const providerNames=['ChatGPT-Konto','OpenAI API','Claude API','DeepSeek API'];
  for(const name of providerNames){const source=`Sprache und Dokumenttyp werden automatisch erkannt. Daten erscheinen als TT.MM.JJJJ. PDF und Word enthalten die Originalseiten. Beim Übersetzen werden Dateien an ${name} gesendet.`;dictionaries.en[source]=`Language and document type are detected automatically. Dates use DD.MM.YYYY. PDF and Word include the original pages. Files are sent to ${name==='ChatGPT-Konto'?'your ChatGPT account':name} when you translate.`;dictionaries.ar[source]=`يُكتشف نوع المستند ولغته تلقائياً. يُعرض التاريخ بصيغة يوم.شهر.سنة. يحتوي PDF وWord على الصفحات الأصلية. عند الترجمة، تُرسل الملفات إلى ${name==='ChatGPT-Konto'?'حساب ChatGPT الخاص بك':name}.`;}
